package com.ptit.poker.ranking.infrastructure;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;import com.ptit.poker.ranking.application.RankingService;import com.ptit.poker.auth.domain.*;import com.ptit.poker.auth.infrastructure.persistence.*;import com.ptit.poker.game.application.GameSessionPersistenceService;import com.ptit.poker.game.domain.state.*;import com.ptit.poker.game.infrastructure.persistence.*;import com.ptit.poker.room.domain.*;import com.ptit.poker.room.infrastructure.persistence.*;import com.ptit.poker.support.TestDatabaseSafetyInitializer;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.*;
@EnabledIfEnvironmentVariable(named="TEST_DB_URL",matches=".+") @EnabledIfEnvironmentVariable(named="TEST_DB_USERNAME",matches=".+") @EnabledIfEnvironmentVariable(named="TEST_DB_PASSWORD",matches=".+")
@ActiveProfiles("test") @ContextConfiguration(initializers=TestDatabaseSafetyInitializer.class) @SpringBootTest
class PlayerRankingMySqlIntegrationTests {@Autowired UserRepository users;@Autowired RoomRepository rooms;@Autowired GameSessionRepository sessions;@Autowired PokerHandRepository hands;@Autowired HandPlayerRepository players;@Autowired GameSessionPersistenceService completion;@Autowired RankingService ranking;@Autowired JdbcTemplate jdbc;private final List<Long> userIds=new ArrayList<>(),roomIds=new ArrayList<>(),sessionIds=new ArrayList<>();private Long roomId,sessionId;
 @AfterEach void cleanup(){for(long id:sessionIds)jdbc.update("DELETE FROM game_sessions WHERE id=?",id);for(long id:roomIds)jdbc.update("DELETE FROM rooms WHERE id=?",id);for(long id:userIds)jdbc.update("DELETE FROM users WHERE id=?",id);}
 @Test void automaticUpdateIsIdempotentAndLeaderboardUsesGlobalOrdering(){Instant now=Instant.parse("2026-08-28T00:00:00Z");UserEntity a=user(),b=user();RoomEntity room=rooms.saveAndFlush(new RoomEntity(unique("rank"),a.getId(),RoomType.PUBLIC,null,6,50,100,1000,RoomStatus.PLAYING,now));roomId=room.getId();roomIds.add(roomId);GameSessionEntity session=sessions.saveAndFlush(new GameSessionEntity(roomId,GameSessionStatus.ACTIVE,now,null));sessionId=session.getId();sessionIds.add(sessionId);PokerHandEntity hand=hands.saveAndFlush(new PokerHandEntity(sessionId,1,1,1,2,50,100,now,now.plusSeconds(10),GamePhase.FINISHED,"",HandEndReason.ALL_OTHERS_FOLDED));players.saveAndFlush(new HandPlayerEntity(hand.getId(),a.getId(),1,1000,1100,100,PokerPlayerState.ACTIVE,true,false,null));players.saveAndFlush(new HandPlayerEntity(hand.getId(),b.getId(),2,1000,900,100,PokerPlayerState.FOLDED,true,false,null));completion.finishSession(sessionId);
  RankingService.CurrentRanking rankedA=ranking.current(a.getId()),rankedB=ranking.current(b.getId());assertThat(rankedA.rating()).isEqualTo(1016);assertThat(rankedB.rating()).isEqualTo(984);assertThat(rankedA.gamesRated()).isOne();assertThat(rankedB.gamesRated()).isOne();ranking.rateCompletedSession(sessionId);assertThat(ranking.current(a.getId()).gamesRated()).isOne();assertThat(ranking.current(b.getId()).gamesRated()).isOne();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM ranking_history WHERE game_session_id=?",Long.class,sessionId)).isEqualTo(2);assertThat(rankedA.rank().longValue()).isLessThan(rankedB.rank().longValue());for(RankingService.CurrentRanking expected:List.of(rankedA,rankedB)){int page=Math.toIntExact((expected.rank()-1)/100),offset=(int)((expected.rank()-1)%100);RankingService.CurrentRanking actual=ranking.leaderboard(page,100).items().get(offset);assertThat(actual.rank()).isEqualTo(expected.rank());assertThat(actual.userId()).isEqualTo(expected.userId());}}
 @Test void unratedUserReturnsDefaultsWithoutCreatingRow(){UserEntity user=user();var value=ranking.current(user.getId());assertThat(value.rank()).isNull();assertThat(value.rating()).isEqualTo(1000);assertThat(value.gamesRated()).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM player_rankings WHERE user_id=?",Long.class,user.getId())).isZero();}
 @Test void concurrentSameSessionAppliesExactlyOnce()throws Exception{UserEntity a=user(),b=user();long id=completed(a,b,100,-100);runTogether(()->ranking.rateCompletedSession(id),()->ranking.rateCompletedSession(id));assertThat(ranking.current(a.getId()).rating()).isEqualTo(1016);assertThat(ranking.current(b.getId()).rating()).isEqualTo(984);assertThat(ranking.current(a.getId()).gamesRated()).isOne();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM ranking_history WHERE game_session_id=?",Long.class,id)).isEqualTo(2);}
 @Test void concurrentDifferentSessionsWithMissingSharedRowSerializeHistory()throws Exception{UserEntity target=user(),x=user(),y=user();long first=completed(target,x,100,-100),second=completed(target,y,-100,100);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM player_rankings WHERE user_id=?",Long.class,target.getId())).isZero();runTogether(()->ranking.rateCompletedSession(first),()->ranking.rateCompletedSession(second));List<Map<String,Object>> history=jdbc.queryForList("SELECT old_rating,new_rating,rating_delta FROM ranking_history WHERE user_id=?",target.getId());assertThat(history).hasSize(2);assertThat(ranking.current(target.getId()).gamesRated()).isEqualTo(2);assertThat(history).allSatisfy(row->assertThat(((Number)row.get("new_rating")).intValue()-((Number)row.get("old_rating")).intValue()).isEqualTo(((Number)row.get("rating_delta")).intValue()));assertThat(history).anySatisfy(row->assertThat(((Number)row.get("old_rating")).intValue()).isEqualTo(1000));}
 @Test void sequentialSessionUsesPriorPersistedRating(){UserEntity target=user(),x=user(),y=user();long first=completed(target,x,100,-100),second=completed(target,y,-100,100);ranking.rateCompletedSession(first);int after=ranking.current(target.getId()).rating();ranking.rateCompletedSession(second);assertThat(jdbc.queryForObject("SELECT old_rating FROM ranking_history WHERE user_id=? AND game_session_id=?",Integer.class,target.getId(),second)).isEqualTo(after);assertThat(ranking.current(target.getId()).gamesRated()).isEqualTo(2);}
 @Test void threePlayerMysqlPersistsExpectedDeltasAndPlacements(){List<UserEntity> u=List.of(user(),user(),user());long id=completedMulti(u,List.of(100L,0L,-100L));ranking.rateCompletedSession(id);List<Map<String,Object>> rows=jdbc.queryForList("SELECT user_id,old_rating,new_rating,rating_delta,placement,participant_count FROM ranking_history WHERE game_session_id=? ORDER BY placement",id);assertThat(rows).extracting(r->((Number)r.get("rating_delta")).intValue()).containsExactly(16,0,-16);assertThat(rows).extracting(r->((Number)r.get("new_rating")).intValue()).containsExactly(1016,1000,984);assertThat(rows).extracting(r->((Number)r.get("placement")).intValue()).containsExactly(1,2,3);assertThat(rows).allSatisfy(r->assertThat(((Number)r.get("participant_count")).intValue()).isEqualTo(3));}
 @Test void fourPlayerTiePersistsCompetitionPlacement(){List<UserEntity> u=List.of(user(),user(),user(),user());long id=completedMulti(u,List.of(500L,200L,200L,-100L));ranking.rateCompletedSession(id);List<Map<String,Object>> rows=jdbc.queryForList("SELECT old_rating,new_rating,rating_delta,placement FROM ranking_history WHERE game_session_id=? ORDER BY user_id",id);assertThat(rows).extracting(r->((Number)r.get("placement")).intValue()).containsExactly(1,2,2,4);assertThat(rows).allSatisfy(r->assertThat(((Number)r.get("new_rating")).intValue()-((Number)r.get("old_rating")).intValue()).isEqualTo(((Number)r.get("rating_delta")).intValue()));}
 @Test void leaderboardUsesAllKeysAndGlobalRanksBeforePagination(){List<UserEntity> u=List.of(user(),user(),user(),user(),user());int[][] values={{1300,2},{1200,10},{1200,5},{1100,3},{1100,3}};for(int i=0;i<u.size();i++)jdbc.update("INSERT INTO player_rankings(user_id,rating,games_rated,peak_rating,updated_at) VALUES(?,?,?,?,NOW(6))",u.get(i).getId(),values[i][0],values[i][1],values[i][0]);List<Long> fixtureIds=u.stream().map(UserEntity::getId).toList();String marks=String.join(",",Collections.nCopies(fixtureIds.size(),"?"));List<Map<String,Object>> expected=jdbc.queryForList("SELECT rank_position,user_id FROM (SELECT ROW_NUMBER() OVER(ORDER BY rating DESC,games_rated DESC,user_id ASC) rank_position,user_id FROM player_rankings WHERE games_rated>0) ranked WHERE user_id IN ("+marks+") ORDER BY rank_position",fixtureIds.toArray());assertThat(expected).hasSize(5).extracting(row->((Number)row.get("user_id")).longValue()).containsExactlyElementsOf(fixtureIds);for(Map<String,Object> row:expected){long rank=((Number)row.get("rank_position")).longValue(),userId=((Number)row.get("user_id")).longValue();int page=Math.toIntExact((rank-1)/2),offset=(int)((rank-1)%2);RankingService.CurrentRanking actual=ranking.leaderboard(page,2).items().get(offset);assertThat(actual.rank()).isEqualTo(rank);assertThat(actual.userId()).isEqualTo(userId);}UserEntity unrated=user();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM player_rankings WHERE user_id=?",Long.class,unrated.getId())).isZero();}
 @Test void historyIsNewestFirstPaginatedAndPrivateByUser(){UserEntity target=user(),other=user();List<Long> ids=new ArrayList<>();for(int i=0;i<3;i++){long id=completed(target,user(),100-i*100L,-100+i*100L);ranking.rateCompletedSession(id);ids.add(id);}long otherSession=completed(other,user(),100,-100);ranking.rateCompletedSession(otherSession);assertThat(ranking.history(target.getId(),0,2)).extracting(x->x.gameSessionId()).containsExactly(ids.get(2),ids.get(1));assertThat(ranking.history(target.getId(),1,2)).extracting(x->x.gameSessionId()).containsExactly(ids.get(0));assertThat(ranking.history(target.getId(),0,10)).extracting(x->x.gameSessionId()).doesNotContain(otherSession).allSatisfy(id->assertThat(id).isIn(ids));}
 private long completed(UserEntity a,UserEntity b,long aNet,long bNet){Instant now=Instant.now();RoomEntity room=rooms.saveAndFlush(new RoomEntity(unique("rank"),a.getId(),RoomType.PUBLIC,null,6,50,100,1000,RoomStatus.PLAYING,now));roomIds.add(room.getId());GameSessionEntity session=sessions.saveAndFlush(new GameSessionEntity(room.getId(),GameSessionStatus.FINISHED,now,now.plusSeconds(10)));sessionIds.add(session.getId());PokerHandEntity hand=hands.saveAndFlush(new PokerHandEntity(session.getId(),1,1,1,2,50,100,now,now.plusSeconds(10),GamePhase.FINISHED,"",HandEndReason.ALL_OTHERS_FOLDED));players.saveAndFlush(new HandPlayerEntity(hand.getId(),a.getId(),1,1000,1000+aNet,100,PokerPlayerState.ACTIVE,true,false,null));players.saveAndFlush(new HandPlayerEntity(hand.getId(),b.getId(),2,1000,1000+bNet,100,PokerPlayerState.FOLDED,true,false,null));return session.getId();}
 private long completedMulti(List<UserEntity> users,List<Long> nets){Instant now=Instant.now();RoomEntity room=rooms.saveAndFlush(new RoomEntity(unique("multi"),users.getFirst().getId(),RoomType.PUBLIC,null,Math.max(6,users.size()),50,100,1000,RoomStatus.PLAYING,now));roomIds.add(room.getId());GameSessionEntity session=sessions.saveAndFlush(new GameSessionEntity(room.getId(),GameSessionStatus.FINISHED,now,now.plusSeconds(10)));sessionIds.add(session.getId());PokerHandEntity hand=hands.saveAndFlush(new PokerHandEntity(session.getId(),1,1,1,2,50,100,now,now.plusSeconds(10),GamePhase.FINISHED,"",HandEndReason.SHOWDOWN));for(int i=0;i<users.size();i++)players.saveAndFlush(new HandPlayerEntity(hand.getId(),users.get(i).getId(),i+1,1000,1000+nets.get(i),100,PokerPlayerState.ACTIVE,true,false,null));return session.getId();}
 private void runTogether(Runnable first,Runnable second)throws Exception{CountDownLatch ready=new CountDownLatch(2),go=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Future<?>> futures=List.of(pool.submit(()->{ready.countDown();go.await();first.run();return null;}),pool.submit(()->{ready.countDown();go.await();second.run();return null;}));assertThat(ready.await(5,TimeUnit.SECONDS)).isTrue();go.countDown();for(Future<?> future:futures)future.get(15,TimeUnit.SECONDS);}finally{pool.shutdownNow();}}
 private UserEntity user(){String s=UUID.randomUUID().toString().replace("-","").substring(0,10);UserEntity u=users.saveAndFlush(new UserEntity("r8_"+s,"hash","r8_"+s+"@example.test",Role.PLAYER,AccountStatus.ACTIVE,5000));userIds.add(u.getId());return u;}private static String unique(String p){return p+"-"+UUID.randomUUID();}}
